	clr.w	is010			; 68000
	addq.l	#4,2(sp)		; skip the MOVEC
	rte

check:	addq.l	#1,NCHECKS
	addq.w	#1,cnum
	cmp.l	d5,d6
	beq.s	.ok
	move.l	a6,-(sp)
	addq.l	#1,FAILCNT
	movea.l	FAILPTR,a6
	move.w	tid,(a6)+
	move.w	cnum,(a6)+
	move.l	d5,(a6)+
	move.l	d6,(a6)+
	move.l	a6,FAILPTR
	movea.l	(sp)+,a6
.ok:	rts

