	dbf	d2,.g
	rts
zerobuf:
	lea	BUFA,a0
	move.w	#2*BUFLEN/4-1,d2
.z:	clr.l	(a0)+
	dbf	d2,.z
	move.w	#$0100,BUFA+BUFLEN+2*23
	move.w	#$0001,BUFA+BUFLEN-2*17
